 void documentScreen(){header("Документы", "Сроки действия и файлы");Button a=btn("+ Добавить документ",blue);a.setOnClickListener(v->documentDialog());add(a);addGap(10);Cursor c=db.all("document",active);try{if(!c.moveToFirst()){empty("Документы ещё не добавлены",this::documentDialog);return;}do{long id=c.getLong(0);LinearLayout x=card();String exp=c.getString(c.getColumnIndexOrThrow("expiryDate"));String state=exp.isEmpty()?"Без срока":(exp.compareTo(today())<0?"ИСТЁК":exp);TextView h=text(c.getString(c.getColumnIndexOrThrow("title")),14,true);h.setTextColor(exp.compareTo(today())<0&&!exp.isEmpty()?Color.rgb(255,74,88):fg());x.addView(h);x.addView(small(c.getString(c.getColumnIndexOrThrow("type"))+" · "+state));Button e=btn("Изменить",blue);e.setOnClickListener(v->documentDialog(id));x.addView(e);add(x);addGap(7);}while(c.moveToNext());}finally{c.close();}}
 void tireScreen(){header("Шины","Комплекты и установка");Button a=btn("+ Добавить комплект",blue);a.setOnClickListener(v->tireDialog());add(a);addGap(10);Cursor c=db.all("tire",active);try{if(!c.moveToFirst()){empty("Комплекты шин ещё не добавлены",this::tireDialog);return;}do{long id=c.getLong(0);LinearLayout x=card();x.addView(text(c.getString(c.getColumnIndexOrThrow("season"))+" · "+c.getString(c.getColumnIndexOrThrow("brand"))+" "+c.getString(c.getColumnIndexOrThrow("model")),14,true));x.addView(small(c.getString(c.getColumnIndexOrThrow("size"))+" · протектор "+fmt(c.getDouble(c.getColumnIndexOrThrow("tread")))+" мм"));x.addView(small(c.getInt(c.getColumnIndexOrThrow("installed"))==1?"УСТАНОВЛЕН":"Не установлен"));Button e=btn("Изменить",blue);e.setOnClickListener(v->tireDialog(id));x.addView(e);add(x);addGap(7);}while(c.moveToNext());}finally{c.close();}}
 void issueScreen(){header("Проблемы","Журнал, а не искусственная диагностика");Button a=btn("+ Добавить проблему",Color.rgb(255,74,88));a.setOnClickListener(v->issueDialog());add(a);addGap(10);Cursor c=db.all("issue",active);try{if(!c.moveToFirst()){empty("Проблем пока нет",this::issueDialog);return;}do{long id=c.getLong(0);LinearLayout x=card();x.addView(text(c.getString(c.getColumnIndexOrThrow("title")),14,true));x.addView(small(c.getString(c.getColumnIndexOrThrow("status"))+" · "+c.getString(c.getColumnIndexOrThrow("date"))+" · "+fmt(c.getDouble(c.getColumnIndexOrThrow("mileage")))+" км"));x.addView(small(c.getString(c.getColumnIndexOrThrow("description"))));Button e=btn("Изменить",blue);e.setOnClickListener(v->issueDialog(id));x.addView(e);add(x);addGap(7);}while(c.moveToNext());}finally{c.close();}}
